// === Tab: Main ===
 /** Another falling sand game, but this time with integrated physics */
/** Things to do:
  - add elements
  - horizontal velocity
*/

// elements
var EMPTY = 0, SAND = 200;

// physics options:
var gravity = 0.1;

var gridWidth = 150, gridHeight = 125;
var grid = [], prev = [];

var brushSize = 5;

function setup() {
  createCanvas(gridWidth * 4, gridHeight * 4);
  for (let i = 0; i < gridWidth * gridHeight; i++) grid[i] = createVector(0, 0, EMPTY);
  fill(255, 255, 0);
  noStroke();
}

function draw() {
  background(0);

  grid[grid.length / 2] = createVector(0, 0, SAND);

  loadCells();
  for (let i = grid.length - 1; i >= 0; --i) {
    const x = i % gridWidth, y = floor(i / gridWidth);
    if (dist((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) - 2, (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))) - 2, x * 4, y * 4) <= sqrt(sq(4) * 2) / 2 * brushSize) 
      if (((window.isBeat || false) || (typeof window.is_silent !== 'undefined' ? !window.is_silent : mouseIsPressed))) grid[i] = createVector(0, 0, SAND);

    if (prev[i].z == SAND) {
      grid[i].y += gravity;
      for (let yStep = 1; yStep < ceil(grid[i].y) + 1; yStep++) {
        if (swapIfAble(i, i + gridWidth * (ceil(grid[i].y / yStep)))) {}
      } if (grid[i].z == SAND) { 
        grid[i] = createVector(0, 0, SAND);
        if (random(1) > 0.5) {
          if (swapIfAble(i, i + gridWidth + 1)) {
          } else if (swapIfAble(i, i + gridWidth - 1)) {}
        } else if (swapIfAble(i, i + gridWidth - 1)) {
        } else if (swapIfAble(i, i + gridWidth + 1)) {}
      }

      square(x * 4, y * 4, 4);
    }
  }
}

function loadCells() {
  for (let i = 0; i < grid.length; i++) {
    prev[i] = grid[i];
  }
}

function swapIfAble(i, j) {
  const cell2_prev = prev[j];
  const x1 = i % gridWidth, x2 = j % gridWidth;
  const diff = x1 - (x2 - x1);
  if (diff > -2 && diff < gridWidth + 1 && j < grid.length && grid[i].z > cell2_prev.z) {

    grid[j] = prev[i];
    grid[i] = cell2_prev;

    return true;
  } return false;
}

function keyPressed() {
  brushSize += keyIsDown(187) - keyIsDown(189);
  brushSize = constrain(brushSize, 1, 100)

  // console.log(keyCode);
}

